    "awa.case": ["Je souhaite recevoir les alertes de BoostImpact sur WhatsApp au numéro {n}", "I would like to receive BoostImpact alerts on WhatsApp at the number {n}", "Ik wil de meldingen van BoostImpact via WhatsApp ontvangen op het nummer {n}"],
