    // Mode de secours des avis (20/10/2026) : file « À publier sur Google » (fonctions SQL admin_avis_a_publier, admin_avis_marquer_publie)
    "con.gbp.titre": ["À publier sur Google", "To publish on Google", "Te publiceren op Google"],
    "con.gbp.chapo": [v => `Réponses aux avis prêtes à partir, tant que l'accès à l'API Google Business Profile n'est pas ouvert. Connecté avec le compte gestionnaire de l'équipe (team@boostimpact.agency) : ouvrez les avis de la fiche, collez la réponse sous l'avis, puis « Marquer comme publiée ». L'heure du clic compte pour la garantie des 24 h. Après ${v.h} h d'attente, une alerte part à l'équipe.`,
      v => `Review replies ready to go, until access to the Google Business Profile API is granted. Signed in with the team's manager account (team@boostimpact.agency): open the listing's reviews, paste the reply under the review, then “Mark as published”. The time of the click counts for the 24-hour guarantee. After ${v.h} hours of waiting, an alert goes to the team.`,
      v => `Antwoorden op reviews die klaarstaan, zolang de toegang tot de Google Business Profile API niet open is. Aangemeld met het beheerdersaccount van het team (team@boostimpact.agency): open de reviews van het profiel, plak het antwoord onder de review en klik op “Markeren als gepubliceerd”. Het tijdstip van de klik telt voor de garantie van 24 uur. Na ${v.h} uur wachten gaat er een melding naar het team.`],
    "con.gbp.auto": ["réponse automatique (règles de l'offre)", "automatic reply (plan rules)", "automatisch antwoord (regels van de formule)"],
    "con.gbp.validee": ["réponse validée par le commerçant", "reply approved by the business owner", "antwoord goedgekeurd door de handelaar"],
    "con.gbp.tenue": ["Garantie déjà tenue (réponse proposée au commerçant)", "Guarantee already met (reply proposed to the owner)", "Garantie al nagekomen (antwoord voorgesteld aan de handelaar)"],
    "con.gbp.depuis": ["à publier depuis le {d}", "to publish since {d}", "te publiceren sinds {d}"],
    "con.gbp.attente": [v => `En attente depuis plus de ${v.h} h : alerte envoyée à l'équipe.`, v => `Waiting for over ${v.h} hours: alert sent to the team.`, v => `Wacht al meer dan ${v.h} uur: melding verstuurd naar het team.`],
    "con.gbp.ouvrir": ["Ouvrir les avis de la fiche", "Open the listing's reviews", "Reviews van het profiel openen"],
    "con.gbp.sans.lien": ["Aucun lien : la fiche Google n'est pas reliée à ce commerce (identifiant de lieu manquant).", "No link: the Google listing isn't linked to this business (place ID missing).", "Geen link: het Google-profiel is niet aan deze zaak gekoppeld (plaats-ID ontbreekt)."],
