    "con.son.ambiance.seule": ["Ambiance du kit : {a}.", "Brand kit mood: {a}.", "Sfeer van de huisstijl: {a}."],
    "con.son.sans": ["Sans bibliothèque de son par Metricool : {res} (publiée avec le son d'origine).", "No sound library through Metricool: {res} (posted with the original sound).", "Geen geluidsbibliotheek via Metricool: {res} (gepubliceerd met het originele geluid)."],
    "con.son.pose": ["Son ajouté", "Sound added", "Geluid toegevoegd"], "con.son.rien": ["Aucun son à poser.", "No sound to add.", "Geen geluid toe te voegen."], "con.son.enregistre": ["Enregistré : son ajouté dans Metricool.", "Saved: sound added in Metricool.", "Opgeslagen: geluid toegevoegd in Metricool."], "con.journal.titre": ["Journal de toutes les étapes", "Log of all steps", "Logboek van alle stappen"],
