    "sty.gab.legende": ["Modèle préféré", "Preferred layout", "Voorkeursopmaak"], "sty.gab.varier": ["Laisser BoostImpact varier entre les trois", "Let BoostImpact vary between the three", "BoostImpact laten afwisselen tussen de drie"],
    "sty.gab.prefere": ["Préférer « {g} »", "Prefer “{g}”", "Voorkeur voor “{g}”"], "sty.gab.impose": ["Toujours ce modèle", "Always this layout", "Altijd deze opmaak"],
    "sty.gab.aide": ["Sans « Toujours ce modèle », BoostImpact garde votre modèle préféré 2 fois sur 3 et varie un peu pour éviter la monotonie.",
      "Without “Always this layout”, BoostImpact keeps your preferred layout 2 times out of 3 and varies a little to avoid monotony.", "Zonder “Altijd deze opmaak” gebruikt BoostImpact uw voorkeursopmaak 2 keer op 3 en wisselt het een beetje af om eentonigheid te vermijden."],
    "sty.apercu.alt": ["Aperçu du modèle {g} avec votre photo et votre style", "Preview of the {g} layout with your photo and your style", "Voorbeeld van de opmaak {g} met uw foto en uw stijl"],
    "sty.logo": ["Votre logo", "Your logo", "Uw logo"], "sty.logo.aucun": ["Aucun logo pour l'instant.", "No logo yet.", "Nog geen logo."],
    "sty.logo.deposer": ["Déposer mon logo", "Upload my logo", "Mijn logo opladen"], "sty.logo.changer": ["Changer de logo", "Change logo", "Ander logo"], "sty.logo.retirer": ["Retirer le logo", "Remove the logo", "Het logo verwijderen"],
    "sty.logo.aide": ["PNG, SVG, JPEG ou WebP, 5 Mo au plus. Enregistré dès le dépôt : BoostImpact s'en sert pour créer votre style. Il est posé petit, à côté de votre nom, jamais sur la photo.", "PNG, SVG, JPEG or WebP, 5 MB max. Saved as soon as you upload it: BoostImpact uses it to create your style. It's placed small, next to your name, never on the photo.", "PNG, SVG, JPEG of WebP, max. 5 MB. Opgeslagen zodra u het oplaadt: BoostImpact gebruikt het om uw stijl te maken. Het staat klein naast uw naam, nooit op de foto."],
    "sty.logo.lu": ["Couleurs tirées de votre logo : vérifiez-les, puis validez.", "Colours taken from your logo: check them, then approve.", "Kleuren uit uw logo gehaald: kijk ze na en keur ze daarna goed."],
