    "sty.mots": ["Vos mots", "Your words", "Uw woorden"], "sty.mots.signature": ["Vos expressions maison", "Your signature phrases", "Uw eigen uitdrukkingen"],
    "sty.mots.signature.aide": ["Une par ligne, 5 au plus. BoostImpact les reprend quand elles s'intègrent bien au texte.", "One per line, 5 max. BoostImpact uses them when they fit the text.", "Eén per regel, max. 5. BoostImpact gebruikt ze wanneer ze goed in de tekst passen."],
    "sty.mots.eviter": ["À ne jamais écrire", "Never write", "Nooit schrijven"],
    "sty.mots.eviter.aide": ["Une expression par ligne, 10 au plus. Une légende qui en contient une est refusée automatiquement.", "One phrase per line, 10 max. A caption containing one is rejected automatically.", "Eén uitdrukking per regel, max. 10. Een bijschrift dat er een bevat, wordt automatisch geweigerd."],
    "sty.valider": ["Ça me plaît", "I like it", "Dit bevalt me"], "sty.enregistrer": ["Enregistrer sans valider", "Save without approving", "Opslaan zonder goed te keuren"],
    "sty.valider.aide": ["« Ça me plaît » dit à BoostImpact que ce style est le vôtre : aucune proposition automatique ne le remplacera. Vous pourrez toujours demander un changement.", "“I like it” tells BoostImpact this style is yours: no automatic suggestion will replace it. You can always ask for a change.", "“Dit bevalt me” zegt BoostImpact dat deze stijl de uwe is: geen enkel automatisch voorstel vervangt hem nog. U kunt altijd een wijziging vragen."],
    "sty.valide.msg": ["C'est noté : votre style est validé (version {v}).", "Done: your style is approved (version {v}).", "Genoteerd: uw stijl is goedgekeurd (versie {v})."],
