    "sty.f.gabarit": ["modèle inconnu", "unknown layout", "onbekende opmaak"], "sty.f.mots_signature": ["5 expressions maison au plus, de 1 à 60 caractères", "5 signature phrases max., 1 to 60 characters each", "max. 5 eigen uitdrukkingen, van 1 tot 60 tekens"],
