    "con.sty.etat.aucun.suite": ["Enregistrez-la pour l'appliquer à ses contenus.", "Save it to apply it to the business's content.", "Sla het op om het op de posts van de zaak toe te passen."],
    "con.sty.demandes": ["Demandes de changement du commerçant", "Change requests from the business", "Vragen om een wijziging van de handelaar"],
    "con.sty.demandes.aide": ["Une demande passe « traitée » dès que BoostImpact enregistre le style.", "A request is marked as handled as soon as BoostImpact saves the style.", "Een vraag wordt “behandeld” zodra BoostImpact de stijl opslaat."],
    "con.sty.demandes.attente": [v => v.n > 1 ? `${v.n} demandes de changement en attente, la plus récente du ${v.d}.` : `Une demande de changement en attente, du ${v.d}.`, v => v.n > 1 ? `${v.n} change requests pending, the latest on ${v.d}.` : `One change request pending, from ${v.d}.`, v => v.n > 1 ? `${v.n} vragen om een wijziging in afwachting, de meest recente van ${v.d}.` : `Eén vraag om een wijziging in afwachting, van ${v.d}.`],
    "con.sty.proposer.logo": ["Proposer les couleurs du logo", "Suggest colours from the logo", "Kleuren uit het logo voorstellen"],
