    "con.sty.propose.msg": ["Couleurs proposées : vérifiez-les, puis enregistrez.", "Colours suggested: check them, then save.", "Kleuren voorgesteld: kijk ze na en sla ze daarna op."],
    "con.sty.logo.retire": ["Logo retiré. Pensez à enregistrer.", "Logo removed. Remember to save.", "Logo verwijderd. Vergeet niet op te slaan."],
    "con.sty.valider": ["Enregistrer et valider pour le client", "Save and approve for the client", "Opslaan en goedkeuren voor de klant"],
    "con.sty.enregistrer": ["Enregistrer", "Save", "Opslaan"],
    "con.sty.valider.aide": ["Valider pour le client verrouille ce style : aucune proposition automatique ne le remplacera. Le commerçant le voit dans « Votre style », validé par BoostImpact, et peut dire qu'il lui plaît ou demander un changement.", "Approving for the client locks this style: no automatic suggestion will replace it. The business sees it in “Your style”, approved by BoostImpact, and can say it likes it or ask for a change.", "Goedkeuren voor de klant vergrendelt deze stijl: geen enkel automatisch voorstel vervangt hem nog. De handelaar ziet hem onder “Uw stijl”, goedgekeurd door BoostImpact, en kan zeggen dat hij hem bevalt of een wijziging vragen."],
    "con.sty.valide.msg": ["Style enregistré et validé pour le client (version {v}).", "Style saved and approved for the client (version {v}).", "Stijl opgeslagen en goedgekeurd voor de klant (versie {v})."],
    "con.sty.enregistre.msg": ["Style enregistré (version {v}), pas encore validé.", "Style saved (version {v}), not approved yet.", "Stijl opgeslagen (versie {v}), nog niet goedgekeurd."],
    "con.sty.apercus": ["Visuels du commerce, à son style", "The business's visuals, in its style", "Beelden van de zaak, in haar stijl"],
    "con.sty.sans.photo": ["Les aperçus prendront une photo du commerce dès qu'il en aura déposé une.", "The previews will use one of the business's photos as soon as it uploads one.", "De voorbeelden gebruiken een foto van de zaak zodra die er een heeft opgeladen."],
    "con.sty.apercus.note": ["Aperçus dessinés dans ce navigateur avec une photo du commerce. Le visuel publié est rendu par le moteur avec les mêmes règles.", "Previews drawn in this browser with one of the business's photos. The published visual is rendered by the engine with the same rules.", "Voorbeelden getekend in deze browser met een foto van de zaak. Het gepubliceerde beeld wordt door de motor gerenderd volgens dezelfde regels."],
    "con.sty.apercu.alt": ["Aperçu du modèle {g} avec une photo du commerce et son style", "Preview of the {g} layout with one of the business's photos and its style", "Voorbeeld van de opmaak {g} met een foto van de zaak en haar stijl"],
    "con.sty.couleurs": ["Couleurs", "Colours", "Kleuren"],
    "con.sty.polices": ["Polices", "Fonts", "Lettertypen"],
