    "dv.r.longue": [v => `Trop longue : ${v.d}, ${v.max} secondes au plus. Coupez-la en plans de 5 à 20 secondes.`, v => `Too long: ${v.d}, ${v.max} seconds max. Cut it into shots of 5 to 20 seconds.`, v => `Te lang: ${v.d}, max. ${v.max} seconden. Knip ze in shots van 5 tot 20 seconden.`],
    "dv.r.courte": ["Trop courte : moins d'une seconde.", "Too short: under one second.", "Te kort: minder dan een seconde."],
    "dv.lourde.titre": ["Vidéo trop lourde : filmez en 1080p", "Video too large: film in 1080p", "Video te groot: film in 1080p"],
    "dv.lourde.texte": ["Une vidéo en 4K pèse bien plus lourd qu'en 1080p, pour un résultat identique une fois publiée. Réglez la caméra en 1080p, ou filmez des plans plus courts.",
      "A 4K video is far heavier than 1080p, for the same result once posted. Set the camera to 1080p, or film shorter shots.", "Een video in 4K is veel zwaarder dan in 1080p, voor hetzelfde resultaat eens hij gepubliceerd is. Stel de camera in op 1080p, of film kortere shots."],
    "dv.lourde.iphone": ["Sur iPhone : dans Réglages, puis Appareil photo, ouvrez la rubrique de l'enregistrement vidéo. Sur les modèles récents, il y a aussi le raccourci HD / 4K en haut de l'écran, en mode Vidéo.",
      "On iPhone: in Settings, then Camera, open the video recording option. Recent models also have the HD / 4K shortcut at the top of the screen, in Video mode.", "Op een iPhone: in Instellingen, daarna Camera, opent u de optie voor video-opname. Recente modellen hebben ook de snelkoppeling HD / 4K bovenaan het scherm, in de modus Video."],
    "dv.lourde.android": ["Sur Android : ouvrez les réglages de l'application Appareil photo (souvent une roue dentée) et cherchez la résolution ou la taille de la vidéo. Le nom et l'emplacement changent selon la marque.",
      "On Android: open the Camera app settings (often a gear icon) and look for the video resolution or size. The name and location vary by brand.", "Op Android: open de instellingen van de app Camera (vaak een tandwiel) en zoek de resolutie of de grootte van de video. De naam en de plaats verschillen per merk."],
    "dv.ens.aucune_video": ["Ajoutez au moins une vidéo.", "Add at least one video.", "Voeg minstens één video toe."],
    "dv.ens.trop_videos": [v => `${v.n} vidéos : 10 au plus par dépôt. Retirez-en, ou faites deux dépôts.`, v => `${v.n} videos: 10 max. per upload. Remove some, or make two uploads.`, v => `${v.n} video's: max. 10 per upload. Verwijder er enkele, of doe twee uploads.`],
    "dv.ens.trop_photos": [v => `${v.n} photos : 10 au plus par dépôt.`, v => `${v.n} photos: 10 max. per upload.`, v => `${v.n} foto's: max. 10 per upload.`],
    "dv.choisies": [v => v.v + " " + pl(v.v, "vidéo", "vidéos") + (v.p ? ", " + v.p + " " + pl(v.p, "photo", "photos") : "") + " " + pl(v.v + v.p, "choisie", "choisies"), v => `${v.v} ${en1(v.v, "video", "videos")}${v.p ? `, ${v.p} ${en1(v.p, "photo", "photos")}` : ""} chosen`, v => `${v.v} ${nl1(v.v, "video", "video's")}${v.p ? `, ${v.p} ${nl1(v.p, "foto", "foto's")}` : ""} gekozen`],
    "dv.envoi.en.cours": [v => `Envoi ${v.i} sur ${v.n}. Gardez cette page ouverte ; si le réseau coupe, l'envoi reprend là où il s'était arrêté.`, v => `Uploading ${v.i} of ${v.n}. Keep this page open; if the connection drops, the upload resumes where it stopped.`, v => `Verzending ${v.i} van ${v.n}. Houd deze pagina open; valt de verbinding weg, dan gaat de verzending verder waar ze gestopt was.`],
    "dv.hors.ligne": ["Connexion perdue : l'envoi reprendra tout seul dès le retour du réseau.", "Connection lost: the upload will resume by itself once you're back online.", "Verbinding verbroken: de verzending gaat vanzelf verder zodra het netwerk terug is."],
    "dv.nouvel.essai": ["Le serveur ne répond pas : nouvel essai en cours.", "The server isn't responding: trying again.", "De server antwoordt niet: nieuwe poging bezig."],
    "dv.interrompu": ["Envoi interrompu. Appuyez sur « Reprendre l'envoi » : il repart du dernier morceau reçu.", "Upload stopped. Tap “Resume the upload”: it restarts from the last piece received.", "Verzending onderbroken. Tik op “Verzending hervatten”: ze gaat verder vanaf het laatst ontvangen stuk."],
    "dv.envoye": [v => `Vidéos envoyées : ${v.v} ${pl(v.v, "vidéo", "vidéos")}${v.p ? ` et ${v.p} ${pl(v.p, "photo", "photos")}` : ""}. Le montage commence, vous serez prévenu quand il sera à valider.`,
      v => `Videos sent: ${v.v} ${en1(v.v, "video", "videos")}${v.p ? ` and ${v.p} ${en1(v.p, "photo", "photos")}` : ""}. Editing is starting; you'll be told when it's ready to approve.`, v => `Video's verstuurd: ${v.v} ${nl1(v.v, "video", "video's")}${v.p ? ` en ${v.p} ${nl1(v.p, "foto", "foto's")}` : ""}. De montage begint; u wordt verwittigd zodra ze goed te keuren is.`],
    "dv.quitter": ["Un envoi de vidéos est en cours : quitter la page l'interrompra.", "A video upload is in progress: leaving the page will stop it.", "Er worden video's verstuurd: als u de pagina verlaat, wordt de verzending onderbroken."],
    "dv.ouvert.titre": ["Un envoi n'est pas terminé", "An upload isn't finished", "Een verzending is niet afgerond"],
    "dv.ouvert.texte": [v => `Commencé ${v.d}. Choisissez à nouveau les mêmes fichiers et appuyez sur « Envoyer les vidéos » : les fichiers déjà reçus ne repartent pas, les autres reprennent là où ils s'étaient arrêtés. Sans suite dans les 24 h, il est annulé.`,
      v => `Started ${v.d}. Choose the same files again and tap “Send the videos”: files already received aren't sent again, the others resume where they stopped. If not finished within 24 hours, it's cancelled.`, v => `Begonnen ${v.d}. Kies opnieuw dezelfde bestanden en tik op “De video's versturen”: bestanden die al ontvangen zijn, worden niet opnieuw verstuurd, de andere gaan verder waar ze gestopt waren. Zonder vervolg binnen 24 uur wordt ze geannuleerd.`],
    "dv.annule": ["Envoi annulé. Les fichiers déjà reçus seront effacés.", "Upload cancelled. Files already received will be deleted.", "Verzending geannuleerd. Bestanden die al ontvangen zijn, worden gewist."],
    "dv.suivi.titre": ["Vos dépôts de vidéos", "Your video uploads", "Uw video-uploads"], "dv.suivi.vide": ["Aucun dépôt pour le moment.", "No uploads yet.", "Nog geen uploads."],
