    // ---- Mise en route claire et travail visible (27/10/2026, audit du parcours, constats 1, 3, 8 à 12, 14, 21 à 23, 31 à 34)
    "nom.offre": ["Votre offre activée", "Your active plan", "Uw actieve formule"],
    "nom.titre": ["Le nom de votre commerce", "Your business name", "De naam van uw zaak"],
    "nom.chapo": ["Vérifiez-le avant tout : vos clients le verront dans les demandes d'avis que nous leur envoyons.", "Check it first: your customers will see it in the review requests we send them.", "Controleer hem eerst: uw klanten zien hem in de reviewverzoeken die wij hun sturen."],
    "nom.lib": ["Nom du commerce", "Business name", "Naam van de zaak"],
    "nom.aide": ["Tel qu'il apparaît sur votre devanture et sur Google.", "As it appears on your shopfront and on Google.", "Zoals hij op uw gevel en op Google staat."],
    "nom.confirmer": ["Confirmer le nom", "Confirm the name", "Naam bevestigen"], "nom.merci": ["Nom confirmé.", "Name confirmed.", "Naam bevestigd."],
    "mer2.chapo.2": ["Pour démarrer, 2 choses.", "To get started, 2 things.", "Om te starten, 2 dingen."], "mer2.chapo.3": ["Pour démarrer, 3 choses.", "To get started, 3 things.", "Om te starten, 3 dingen."],
    "mer2.demande.etat": ["Demande envoyée", "Request sent", "Aanvraag verstuurd"],
    "mer2.google.titre": ["Donner l'accès à votre fiche Google", "Give access to your Google profile", "Toegang geven tot uw Google-profiel"],
    "mer2.google.chapo": ["Vous ajoutez notre adresse comme administrateur. Vous restez propriétaire, et vous pouvez retirer l'accès quand vous voulez.", "You add our address as a manager. You remain the owner and can remove access whenever you like.", "U voegt ons adres toe als beheerder. U blijft eigenaar en kunt de toegang intrekken wanneer u wilt."],
    "mer2.google.pas.1": ["Connectez-vous à Google avec le compte de votre fiche, puis cherchez le nom de votre établissement sur Google.", "Sign in to Google with your profile's account, then search for your business name on Google.", "Meld u bij Google aan met het account van uw profiel en zoek dan de naam van uw zaak op Google."],
    "mer2.google.pas.2": ["Dans le panneau « Votre établissement sur Google », touchez le menu ⋮.", "In the panel showing your business on Google, tap the ⋮ menu.", "Tik in het paneel van uw zaak op Google op het menu ⋮."],
    "mer2.google.pas.3": ["Choisissez « Paramètres de la fiche d'établissement ».", "Choose your Business Profile settings.", "Kies de instellingen van uw bedrijfsprofiel."],
    "mer2.google.pas.4": ["Ouvrez « Utilisateurs et accès », puis « Ajouter ».", "Open the users and access section, then add a user.", "Open het onderdeel gebruikers en toegang en voeg een gebruiker toe."],
    "mer2.google.pas.5": ["Saisissez <span class=\"fort casse\" translate=\"no\">team@boostimpact.agency</span> et gardez le rôle « Administrateur ».", "Enter <span class=\"fort casse\" translate=\"no\">team@boostimpact.agency</span> with the Manager role.", "Vul <span class=\"fort casse\" translate=\"no\">team@boostimpact.agency</span> in met de rol Beheerder."],
    "mer2.google.pas.6": ["Touchez « Inviter ». C'est tout : nous acceptons l'invitation de notre côté.", "Send the invitation. That's all: we accept it on our side.", "Verstuur de uitnodiging. Dat is alles: wij aanvaarden ze aan onze kant."],
    "mer2.google.fait.bouton": ["C'est fait", "Done", "Gedaan"],
    "mer2.google.declare": ["Merci. Nous vérifions l'accès et vous prévenons.", "Thank you. We're checking the access and will let you know.", "Bedankt. Wij controleren de toegang en laten het u weten."],
    "mer2.google.fait": ["C'est fait : nous avons accès à votre fiche.", "Done: we have access to your profile.", "Gedaan: wij hebben toegang tot uw profiel."],
    "mer2.sans.fiche": ["Je n'ai pas encore de fiche Google, ou elle n'est pas à mon nom", "I don't have a Google profile yet, or it isn't in my name", "Ik heb nog geen Google-profiel, of het staat niet op mijn naam"],
    "mer2.sans.fiche.texte": ["La création de votre fiche est comprise dans votre offre. Dites-nous votre cas :", "Creating your profile is included in your plan. Tell us your situation:", "Het aanmaken van uw profiel zit in uw formule. Vertel ons uw situatie:"],
    "mer2.cas.pas_de_fiche": ["Je n'ai pas de fiche Google", "I don't have a Google profile", "Ik heb geen Google-profiel"],
    "mer2.cas.pas_a_mon_nom": ["Une fiche existe, mais je n'y ai pas accès (elle n'est pas à mon nom)", "A profile exists, but I can't access it (it isn't in my name)", "Er bestaat een profiel, maar ik heb er geen toegang toe (het staat niet op mijn naam)"],
    "mer2.fiche.demander": ["Demander la création de ma fiche", "Ask for my profile to be created", "Het aanmaken van mijn profiel aanvragen"],
    "mer2.fiche.merci": ["Demande enregistrée. Notre équipe vous contacte.", "Request saved. Our team will contact you.", "Aanvraag opgeslagen. Ons team neemt contact met u op."],
    "mer2.fiche.demandee": ["Demande envoyée le {d}. Voici ce qui va se passer :", "Request sent on {d}. Here's what happens next:", "Aanvraag verstuurd op {d}. Dit gebeurt er nu:"],
    "mer2.fiche.suite.1": ["Notre équipe vous contacte pour créer votre fiche, ou pour récupérer celle qui existe.", "Our team contacts you to create your profile, or to recover the existing one.", "Ons team neemt contact met u op om uw profiel aan te maken, of om het bestaande terug te krijgen."],
    "mer2.fiche.suite.2": ["Google vérifie la fiche, en général par un code ou une courte vidéo : nous vous guidons.", "Google verifies the profile, usually with a code or a short video: we guide you through it.", "Google verifieert het profiel, meestal met een code of een korte video: wij begeleiden u."],
    "mer2.fiche.suite.3": ["Nos délais garantis démarrent le jour où Google a vérifié la fiche.", "Our guaranteed timescales start on the day Google verifies the profile.", "Onze gegarandeerde termijnen starten op de dag dat Google het profiel verifieert."],
    "mer2.fiche.annuler": ["Finalement, j'ai accès à ma fiche", "Actually, I can access my profile", "Ik heb toch toegang tot mijn profiel"],
    "mer2.photos.titre": ["Envoyer vos photos", "Send your photos", "Uw foto's sturen"], "mer2.photos.titre.google": ["Envoyer une ou deux photos (facultatif)", "Send one or two photos (optional)", "Eén of twee foto's sturen (niet verplicht)"],
    "mer2.photos.texte": ["3 photos de votre commerce, de vos plats ou de vos produits : elles deviennent vos premières publications, que vous validez.", "3 photos of your business, your dishes or your products: they become your first posts, which you approve.", "3 foto's van uw zaak, uw gerechten of uw producten: ze worden uw eerste posts, die u goedkeurt."],
    "mer2.photos.google": [v => `Elles servent à vos ${v.n} publications Google du mois. Vous les validez avant qu'elles partent.`, v => `They're used for this month's ${v.n} Google posts. You approve them before they go out.`, v => `Ze dienen voor de ${v.n} Google-posts van deze maand. U keurt ze goed voor ze verschijnen.`],
    "mer2.photos.fait": [v => v.n > 1 ? `${v.n} photos reçues. Vous pouvez en envoyer d'autres quand vous voulez.` : "1 photo reçue. Vous pouvez en envoyer d'autres quand vous voulez.", v => v.n === 1 ? "1 photo received. You can send more whenever you like." : `${v.n} photos received. You can send more whenever you like.`, v => v.n === 1 ? "1 foto ontvangen. U kunt er wanneer u wilt meer sturen." : `${v.n} foto's ontvangen. U kunt er wanneer u wilt meer sturen.`],
    "mer2.reseaux.titre": ["Connecter Facebook et Instagram", "Connect Facebook and Instagram", "Facebook en Instagram koppelen"],
    "mer2.reseaux.a_faire": ["Nous vous envoyons par email un lien vers notre outil de programmation (valable 3 jours). Ouvrez-le et connectez Facebook et Instagram : nous publions ensuite seulement ce que vous avez validé.", "We email you a link to our scheduling tool (valid for 3 days). Open it and connect Facebook and Instagram: we then post only what you've approved.", "Wij mailen u een link naar onze planningstool (3 dagen geldig). Open hem en koppel Facebook en Instagram: wij publiceren daarna alleen wat u hebt goedgekeurd."],
