    "avis.sensible.approuver": ["J'approuve cette réponse", "I approve this reply", "Ik keur dit antwoord goed"], "avis.sensible.en.parler": ["Je veux en parler", "I'd like to talk about it", "Ik wil erover praten"],
    "avis.sensible.regle": ["Si vous approuvez, nous publions exactement ce texte sur votre fiche. Sinon, nous vous appelons.", "If you approve, we publish exactly this text on your profile. Otherwise, we call you.", "Als u goedkeurt, publiceren wij precies deze tekst op uw profiel. Zo niet, dan bellen wij u."],
    "avis.sensible.approuvee": ["Vous avez approuvé cette réponse le {d} : nous la publions sur votre fiche.", "You approved this reply on {d}: we're publishing it on your profile.", "U hebt dit antwoord goedgekeurd op {d}: wij publiceren het op uw profiel."],
    "avis.sensible.en.parler.fait": ["Vous avez demandé à en parler le {d} : nous vous appelons.", "You asked to talk about it on {d}: we'll call you.", "U vroeg op {d} om erover te praten: wij bellen u."],
    "avis.sensible.approuvee.msg": ["Réponse approuvée : nous la publions sur votre fiche.", "Reply approved: we're publishing it on your profile.", "Antwoord goedgekeurd: wij publiceren het op uw profiel."],
    "avis.sensible.en.parler.msg": ["Demande envoyée : nous vous appelons pour en parler.", "Request sent: we'll call you to talk about it.", "Aanvraag verstuurd: wij bellen u om erover te praten."],
    "avis.vide.sans.acces": ["Vos avis Google apparaîtront ici dès que nous aurons accès à votre fiche.", "Your Google reviews will appear here as soon as we have access to your profile.", "Uw Google-reviews verschijnen hier zodra wij toegang hebben tot uw profiel."],
