    "photos.plafond.google": [v => `Vos ${v.n} publications Google du mois sont déjà prévues : une nouvelle photo ne fera pas de publication avant le 1er ${mois("fr")[v.mois]}.`, v => `This month's ${v.n} Google posts are already planned: a new photo won't make a post before 1 ${mois("en")[v.mois]}.`, v => `De ${v.n} Google-posts van deze maand zijn al gepland: een nieuwe foto wordt geen post vóór 1 ${mois("nl")[v.mois]}.`],
