    "offre.premium.delegation": ["Mode délégation", "Delegation mode", "Delegatiemodus"],
    "offre.premium.delegation.active": ["Activé", "On", "Actief"], "offre.premium.delegation.inactive": ["Pas encore activé", "Not on yet", "Nog niet actief"],
    "offre.premium.delegation.activer": ["Avec le mode délégation, votre validation devient facultative : sans réponse de votre part {h} h après l'envoi, le contenu est publié. Pour l'activer, écrivez-nous à info@boostimpact.agency : nous vous envoyons l'accord écrit prévu par nos conditions de vente. Vous pourrez en sortir à tout moment par email.",
      "With delegation mode, your approval becomes optional: with no reply from you {h} hours after it's sent, the content is published. To turn it on, write to us at info@boostimpact.agency: we'll send you the written agreement set out in our terms of sale. You can leave it at any time by email.",
      "Met de delegatiemodus wordt uw goedkeuring facultatief: zonder antwoord van u {h} uur na verzending wordt de post gepubliceerd. Om hem te activeren, schrijft u ons op info@boostimpact.agency: wij sturen u het schriftelijke akkoord uit onze verkoopvoorwaarden. U kunt er op elk moment per e-mail uit stappen."],
    "offre.premium.delegation.sortir": ["Pour en sortir, écrivez à info@boostimpact.agency.", "To leave it, write to info@boostimpact.agency.", "Om eruit te stappen, schrijft u naar info@boostimpact.agency."],
    "offre.dessus.titre": ["Ce que l'offre {nom} ajoute", "What the {nom} plan adds", "Wat de formule {nom} toevoegt"],
    "offre.dessus.std.1": [v => `Vos photos deviennent aussi des publications Instagram et Facebook : ${v.n} contenus par mois.`, v => `Your photos also become Instagram and Facebook posts: ${v.n} pieces of content a month.`, v => `Uw foto's worden ook posts op Instagram en Facebook: ${v.n} posts per maand.`],
    "offre.dessus.std.2": ["Les réponses à vos avis sont publiées pour vous, sans que vous ayez à intervenir.", "Replies to your reviews are published for you, with nothing for you to do.", "De antwoorden op uw reviews worden voor u gepubliceerd, zonder dat u iets moet doen."],
